CREATE OR REPLACE FUNCTION calculate_tes(p_txkey integer)
RETURNS numeric AS $$
DECLARE
    v_engagement text;
    v_score numeric;
BEGIN
    -- Get the engagement value from therapy_details JSONB column
    SELECT therapy_details->>'engagement' INTO v_engagement
    FROM treatmentbasics
    WHERE txkey = p_txkey;

    -- Map engagement to score
    CASE v_engagement
        WHEN 'High' THEN v_score := 3;
        WHEN 'Medium' THEN v_score := 2;
        WHEN 'Low' THEN v_score := 1;
        ELSE v_score := 0;
    END CASE;

    RETURN v_score;
END;
$$ LANGUAGE plpgsql;
